/*
 * A328365  Irregular triangle read by rows, T(n,k), n >= 1, k >= 1, in which
 *          row n lists in reverse order the partitions of n into consecutive
 *          parts.
 * https://oeis.org/A328365
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is generated by concatenating, row by row, the parts of all
 *            partitions of each integer into consecutive increasing parts.
 *            Each row n lists the partitions in decreasing order of the
 *            number of parts; within each partition the parts appear in
 *            increasing order
 * Range:     u8 n <= 1362, u16 n <= 8719, u32 n <= 8719, u64 n <= 8719,
 *            u128 n <= 8719, big any n
 * Helpers:   max_parts_with_sum
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/max_parts_with_sum.h"

seq_t a(idx_t n) {
    idx_t target = n;
    idx_t cur = 1;                /* current 1–based position in the sequence */

    for (idx_t row = 1; ; ++row) {
        seq_t rn = (seq_t)row;
        seq_t two_rn = rn + rn;
        idx_t k_max = max_parts_with_sum(row);

        for (idx_t k = k_max; k >= 1; --k) {
            seq_t kseq = (seq_t)k;
            if (two_rn % kseq != 0) continue;

            seq_t temp = two_rn / kseq - kseq + 1;
            if (temp <= 0 || (temp & 1)) continue;   /* must be even and positive */
            seq_t a_start = temp >> 1;               /* a = (temp)/2 */

            for (idx_t part = 0; part < k; ++part) {
                if (cur == target) {
                    return a_start + (seq_t)part;
                }
                ++cur;
            }
        }
    }
}
